const MENTION_SEARCH_CONCURRENCY = 3

const MENTION_FUSE_OPTIONS = {
  includeScore: true,
  minMatchCharLength: 3,
  keys: ["name", "searchIndex", "file"]
}

function isSameOrChildPath(parentPath, childPath) {
  if (!parentPath || !childPath) return false
  const normalizedParentPath = parentPath.endsWith('/') ? parentPath : `${parentPath}/`
  return childPath === parentPath || childPath.startsWith(normalizedParentPath)
}

/** Run `worker` over `items` with at most `limit` promises in flight. */
async function mapWithConcurrency(items, limit, worker) {
  const results = []
  let nextIndex = 0
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (nextIndex < items.length) {
      const current = nextIndex++
      results[current] = await worker(items[current])
    }
  })
  await Promise.all(runners)
  return results
}

/**
 * Distinct roots a mention query has to search: the active project plus its
 * dependencies that live OUTSIDE its tree. Sub projects nested in the active
 * project root are dropped - the backend search already covers them.
 */
function getSearchRoots(project) {
  const candidates = [project, ...getRelatedProjects(project)]
    .filter(candidate => candidate && candidate.$api && candidate.abs_project_path)

  const roots = []
  for (const candidate of candidates) {
    const covered = roots.some(root => isSameOrChildPath(root.abs_project_path, candidate.abs_project_path))
    if (!covered) roots.push(candidate)
  }
  return roots
}
```

