  controller.setProgress({ stage: 'loading', project: project.project_name })

  const combined = await buildMentions(project)
  controller.checkCancelled()

  const rank = () => new Fuse(combined, MENTION_FUSE_OPTIONS)
    .search(query)
    .map(result => ({ ...result.item, score: result.score }))
    .filter(({ score }) => score < 0.25)
    .slice(0, limit)

  if (!query || query.length < 2) {
    return rank()
  }

  const seenFiles = new Set()

  await mapWithConcurrency(getSearchRoots(project), MENTION_SEARCH_CONCURRENCY, async searchRoot => {
    const fileResults = await searchProjectFiles(searchRoot, query, limit)
    controller.checkCancelled()

    for (const fileResult of fileResults) {
      const key = (fileResult.file || fileResult.name).toLowerCase()
      if (seenFiles.has(key)) continue
